import{at as e,it as t,n,vt as r}from"./chunks/framework.CinQa4et.js";import"./chunks/assets.BFXjnKeG.js";var i=JSON.parse(`{"title":"サイト設定と共通デザイン","description":"","frontmatter":{},"headers":[],"relativePath":"guides/sites.md","filePath":"guides/sites.md","lastUpdated":1793464466000}`),a={name:`guides/sites.md`};function o(n,i,a,o,s,c){return r(),t(`div`,null,[...i[0]||=[e(`<h1 id="サイト設定と共通デザイン" tabindex="-1">サイト設定と共通デザイン <a class="header-anchor" href="#サイト設定と共通デザイン" aria-label="Permalink to “サイト設定と共通デザイン”">​</a></h1><p>ヘッダーで対象サイトを選び、「サイト設定」を開きます。サイト管理者またはSuperuserが変更できます。新しいサイトの追加はSuperuserが「JevSense管理」で行います。</p><h2 id="基本設定" tabindex="-1">基本設定 <a class="header-anchor" href="#基本設定" aria-label="Permalink to “基本設定”">​</a></h2><table tabindex="0"><thead><tr><th>項目</th><th>入力例・意味</th></tr></thead><tbody><tr><td>サイト名</td><td>管理画面で使う名前。後から変更可能</td></tr><tr><td>サイトID</td><td>SDKのdata-siteと一致。作成後は変更不可</td></tr><tr><td>許可するオリジン</td><td><a href="https://example.com" target="_blank" rel="noreferrer">https://example.com</a>。パス・末尾スラッシュなし</td></tr><tr><td>収集する経路</td><td>/ja/。前方一致、1行に1つ</td></tr><tr><td>収集しない経路</td><td>/ja/account、/ja/checkout、/ja/search等</td></tr><tr><td>メタデータ送信</td><td>対象ページの情報を確認してから有効化</td></tr><tr><td>有効な閲覧の表示時間</td><td>ミリ秒。短時間表示を判断材料から除く基準</td></tr><tr><td>必要な有効閲覧数</td><td>判定を始めるための有効ページ閲覧数</td></tr></tbody></table><p>新設サイトは送信と施策が無効です。設定を確認して「設定を保存」します。収集範囲の変更後は対象ページを再読み込みし、SDKに新しい設定を読み込ませます。</p><h3 id="オリジンとパスの違い" tabindex="-1">オリジンとパスの違い <a class="header-anchor" href="#オリジンとパスの違い" aria-label="Permalink to “オリジンとパスの違い”">​</a></h3><p><code>https://adobe.customer-experience.dev/ja/</code>を対象にする例です。</p><ul><li>オリジン：<code>https://adobe.customer-experience.dev</code></li><li>収集する経路：<code>/ja/</code></li><li>表示ページ：施策側で、たとえば完全一致<code>/ja/</code></li></ul><p>収集する範囲と表示するページは別です。商品ページを判断材料として集め、トップページだけに案内を表示できます。</p><h2 id="追加イベントと状態" tabindex="-1">追加イベントと状態 <a class="header-anchor" href="#追加イベントと状態" aria-label="Permalink to “追加イベントと状態”">​</a></h2><p>独自クリック・応募・予約・カートなどを連携する場合だけ、イベント名・状態名を登録します。SDKは登録済みの名前だけを受け付けます。<a href="./../integration/sdk#任意のイベント・状態">追加連携</a>を参照してください。</p><h2 id="サイト共通の基本デザイン" tabindex="-1">サイト共通の基本デザイン <a class="header-anchor" href="#サイト共通の基本デザイン" aria-label="Permalink to “サイト共通の基本デザイン”">​</a></h2><p>「共通デザイン」では、そのサイトの全標準施策へ適用する見た目を設定します。</p><table tabindex="0"><thead><tr><th>対象</th><th>調整内容</th></tr></thead><tbody><tr><td>共通</td><td>背景・文字・ボタン色、フォント、文字サイズ、角丸、余白</td></tr><tr><td>モーダル</td><td>幅、背面の暗さ</td></tr><tr><td>フローティング</td><td>幅、右下/左下、画面端との余白</td></tr><tr><td>通知バー</td><td>上部/下部</td></tr></tbody></table><p><img src="/jev-personalization/images/design.png" alt="共通デザイン" width="1440" height="1892"></p><p>右のプレビューで形式を切り替えながら確認できます。入力中の変更は、保存するまでサイトへ反映しません。保存すると配信中の施策にも適用します。</p><h2 id="独自javascriptの許可" tabindex="-1">独自JavaScriptの許可 <a class="header-anchor" href="#独自javascriptの許可" aria-label="Permalink to “独自JavaScriptの許可”">​</a></h2><p>サイト単位で許可します。コードの作成・変更・プレビューはサイト管理者またはSuperuserだけが行えます。コードはサイトと同じ権限で動くため、信頼できるものだけを登録します。<a href="./presentation">表示形式と独自コード</a>も確認してください。</p>`,18)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};